export const dictionaries: Record<Locale, Messages> = { ru, en, kk };
export function getMessages(locale: Locale): Messages { return dictionaries[locale] ?? ru; }
export function translate(locale: Locale, key: MessageKey, vars?: Record<string, string | number>): string {
  let value: string = getMessages(locale)[key];
  for (const [name, replacement] of Object.entries(vars ?? {})) value = value.replaceAll(`{${name}}`, String(replacement));
  return value;
}
// Server Actions and API routes return message keys; unknown strings are shown unchanged.
export function isMessageKey(value: string): value is MessageKey { return Object.prototype.hasOwnProperty.call(ru, value); }
export function translateMessage(locale: Locale, message: string): string { return isMessageKey(message) ? translate(locale, message) : message; }
